contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Create a fake token that reverts on transferFrom
        // We'll use an EOA as caddress; calling it with fallback returns false but doesn't revert
        address fakeToken = address(0x123);
        address from = address(0x456);
        address[] memory tos = new address[](1);
        tos[0] = address(0x789);
        uint[] memory vals = new uint[](1);
        vals[0] = 100;
        // The reference reverts on failed call, so try/catch to observe revert vs. no revert
        bool success;
        try c.transfer(from, fakeToken, tos, vals) {
            success = true;
        } catch {
            success = false;
        }
        // In reference version, the call reverts => success is false
        // In bug version, it returns false but continues and returns true => success is true
        // We assertFalse(success) to check that the ORIGINAL reference reverts
        assertTrue(!success);
    }
}

